-- ===========================================================================
-- The six role scorecards, seeded from Documents/DTG/KPI/Role.
--
-- Generated from backend/app/data/kpi_role_templates.json rather than retyped,
-- so the weights and wording match the role documents exactly. Re-runnable:
-- templates are matched on  and their items replaced.
-- ===========================================================================

begin;

-- Geotechnical Monitoring Engineer -- 10 KPIs, weights total 100
values ('monitoring_engineer', 'Geotechnical Monitoring Engineer', '2026', 'Monitoring_Engineer_KPI_2026.docx', '[''60% Safety judgement & response'', ''25% Delivery & data quality'', ''15% Learning, improvement & teamwork'']')
on conflict (code) do update
   set title = excluded.title,
       source_document = excluded.source_document,
       bands = excluded.bands,
       updated_at = now();

delete from public.kpi_template_items where template_id = (select id from public.kpi_role_templates where code = 'monitoring_engineer');

-- Underground Monitoring Engineer -- 10 KPIs, weights total 100
values ('underground_monitoring', 'Underground Monitoring Engineer', '2026', 'Underground_Monitoring_KPI_2026.docx', '[''45% Technical quality'', ''35% Delivery, records & risk'', ''15% Initiative & execution'', ''5% Safety & teamwork'']')
on conflict (code) do update
