-- Finance & Administration Assistant -- 10 KPIs, weights total 100
values ('finance_administration_assistant', 'Finance & Administration Assistant', '2026', 'Finance_Administration_Assistant_KPI_2026.docx', '[''30% Compliance & records'', ''22% Payroll & cash'', ''20% Budget & reporting'', ''16% Transactions & people'', ''12% Office & improvement'']')
