       bands = excluded.bands,
       updated_at = now();

delete from public.kpi_template_items where template_id = (select id from public.kpi_role_templates where code = 'finance_administration_assistant');

commit;

-- Every template must total 100, or a scorecard rated 3 throughout will not
-- come to 100 and every band downstream is wrong.
select t.code, count(*) as items, sum(i.weight) as total_weight
  from public.kpi_role_templates t
  join public.kpi_template_items i on i.template_id = t.id
 group by t.code order by t.code;
